import { expect, test } from "bun:test";
import { SimpleFastCounter32, seededRandom } from "./random";

test("old and new random give the same output", () => {
	const oldRandom = SimpleFastCounter32();
	for (let i = 0; i < expectedSequence.length; i++) {
		expect(oldRandom(), `Failed after ${i + 1} calls`).toBe(
			expectedSequence[i],
		);

		expect(seededRandom(i), `Failed after ${i + 1} calls`).toBe(
			expectedSequence[i],
		);
	}
});

